function render(){
 const c=cases.find(x=>x.id===current);if(!c)return;
 const st=state();const answers=c.questions.map((q,i)=>{const a=st.answers[i]||{};return '<section class="refiq"><h3>'+h(q.q)+'</h3><div class="refiqchoices">'+q.options.map((o,j)=>'<button type="button" data-clp-pick="'+i+':'+j+'" '+(a.checked?'disabled':'')+' class="'+(a.selected===j?'refiqpicked ':'')+(a.checked?(j===q.answer?'refiqright':a.selected===j?'refiqwrong':''):'')+'">'+String.fromCharCode(65+j)+'. '+h(o)+'</button>').join('')+'</div>'+(a.checked?'<div class="refiqfeedback '+(a.selected===q.answer?'refiqfeedback-correct':'refiqfeedback-wrong')+'" role="status"><b>'+(a.selected===q.answer?'✓ Correct':'✕ Review the interpretation')+'</b><p>'+h(q.why)+'</p><button type="button" data-clp-retry="'+i+'">Try again</button></div>':'<button type="button" class="refsubmit" data-clp-check="'+i+'">Check answer</button>')+'</section>'}).join('');
 let ddx='';
 if(c.differentials.length){const opts=c.differentials;
 ddx='<section class="refbox refguided"><h3>🩺 Differential diagnosis · Select and rank</h3><p>Choose three, rank them with ↑ / ↓, then mark your #1 as ★ Lead.</p><div class="refoptions">'+opts.map((d,i)=>'<div class="refoption '+(st.selected.includes(i)?'is-selected':'')+'"><button type="button" class="refoptionselect" data-clp-ddx="'+i+'" '+(st.submitted?'disabled':'')+'>'+(st.selected.includes(i)?'☑':'☐')+' '+h(d.name)+'</button><button type="button" data-clp-lead="'+i+'" '+(st.submitted?'disabled':'')+'>'+(st.lead===String(i)?'★ Lead':'☆ Lead')+'</button></div>').join('')+'</div><div class="refbox refshortlist"><h3>Your ranked shortlist</h3>'+st.selected.map((i,j)=>'<p>'+(j+1)+'. '+h(opts[i].name)+' <button data-clp-move="'+i+':-1" '+(j===0||st.submitted?'disabled':'')+'>↑</button> <button data-clp-move="'+i+':1" '+(j===st.selected.length-1||st.submitted?'disabled':'')+'>↓</button></p>').join('')+'</div>'+(st.error?'<p role="alert">'+h(st.error)+'</p>':'')+(st.submitted?'<h3>📊 Evidence comparison</h3><table class="refcompare"><thead><tr><th>Priority</th><th>Differential</th><th>Supporting evidence</th><th>Against / uncertainty</th><th>Next test</th></tr></thead><tbody>'+opts.map((d,i)=>'<tr class="refcompare-'+d.tier+'"><td>'+h(d.tier)+'</td><td>'+h(d.name)+'</td><td>'+h(d.support)+'</td><td>'+h(d.against)+'</td><td>'+h(d.test)+'</td></tr>').join('')+'</tbody></table>':'<button type="button" class="refsubmit" data-clp-ddx-submit="1">Submit ranking · Compare evidence</button>')+'</section>';
 }
 const options='<option value="001">Case 001 · Dog · PU/PD and weight loss (approved prototype)</option>'+cases.map(k=>'<option value="'+k.id+'" '+(k.id===c.id?'selected':'')+'>Case '+k.id+' · '+h(k.title)+'</option>').join('');
 const html='<div class="refcase refnewlibrary"><div class="refbox refheader"><label for="vpqReferralCasePick">🐾 Referral patient</label><select class="refselect" id="vpqReferralCasePick">'+options+'</select><p class="refsmall">'+h(c.kind)+' · '+h(c.source)+'</p></div><details class="refbox refsection" open><summary>🐾 History and physical examination</summary><div class="refsectionbody"><p><b>Signalment:</b> '+h(c.signal)+'</p><p><b>History:</b> '+h(c.history)+'</p><p><b>Exam:</b> '+h(c.exam)+'</p></div></details><h3>🧪 Ancillary testing</h3><div class="refresultsgrid"><div>'+c.panels.filter((p,i)=>i===0).map(table).join('')+'</div><div>'+c.panels.filter((p,i)=>i>0).map(table).join('')+'</div></div><details class="refbox refsection"><summary>📷 Photos to add · '+c.photos.length+'</summary><div class="refsectionbody">'+c.photos.map(t=>'<p>📷 '+h(t)+' — image not yet supplied</p>').join('')+'</div></details><p class="refsmall"><b>Smear / specimen:</b> '+h(c.smear)+'</p><section class="refbox refinterpret"><h3>🔎 Interpret the laboratory findings first</h3>'+answers+'</section><div class="refpracticegrid no-images"><div class="refpracticequestions">'+ddx+'</div></div><details class="refbox refsection"><summary>🎓 Advanced written challenge</summary><div class="refsectionbody"><p>Explain the key laboratory pattern, differential reasoning, limitations, and next tests in your own words.</p><textarea data-clp-note="1" rows="5" placeholder="Your clinical reasoning…">'+h(st.notes||'')+'</textarea><button type="button" data-clp-advanced="1">Submit notes · Open teaching comparison</button>'+(st.advanced?'<div class="refiqfeedback"><b>Teaching review</b><p>'+h(c.questions.map(q=>q.why).join(' '))+'</p>'+(c.differentials.length?'<p>'+h(c.differentials.map(x=>x.name+': '+x.test).join('; '))+'</p>':'')+'</div>':'')+'</div></details><div class="refbuttons"><button type="button" data-clp-reset="1">Restart this case</button></div></div>';
 window.VPQ_REFERRAL_MODAL.show('🔬 Referral Patients · Clinical Pathology',html);
}
